mapper.select:
SELECT COUNT(*)
FROM tbl_reservation
WHERE bno      = #{bno}
  AND res_date = #{resDate}
  AND status   = 'RESERVED'
  AND ( start_time < #{endTime}
    AND end_time   > #{startTime} )

mapper.update:
UPDATE tbl_reservation
SET status = 'CANCELLED'
WHERE res_id = #{resId}
  AND userid = #{userid}
  AND status = 'RESERVED'
